mapper.select:
SELECT va.item_id AS counterpartId, va.item_name AS counterpartName, va.auxiliary AS assistType, i.subject_code AS subjectCode, i.subject_name AS subjectName, IFNULL(i.debit_amount, 0) AS debitAmount, IFNULL(i.credit_amount, 0) AS creditAmount, i.summary AS summary, v.id AS voucherId, v.word AS voucherWord, v.voucher_date AS voucherDate, v.voucher_year AS voucherYear, v.voucher_month AS voucherMonth, i.id AS voucherItemId FROM voucher_item i INNER JOIN voucher v ON v.id = i.voucher_id AND v.deleted = 'n' AND v.sender_id IS NOT NULL AND v.sender_id <> '' INNER JOIN voucher_auxiliary va ON va.voucher_item_id = i.id AND va.auxiliary = #{assistType} WHERE i.book_id = #{bookId}
AND va.item_id = #{counterpartId}
AND (
i.subject_code = #{p} OR i.subject_code LIKE CONCAT(#{p}, '.%') OR i.subject_code LIKE CONCAT(#{p}, '%')
)
ORDER BY v.voucher_date ASC, v.word_num ASC, i.id ASC
